  id:"q-iamspe2021-003", banca:"IAMSPE", real:true, ano:2021, numeroNaProva:3,
  areaId:"area-cm", especialidadeId:"esp-cardio", assuntoId:"ass-has",
  enunciado:"Um paciente de 28 anos de idade, branco, com IMC de 24 kg/m², sem antecedentes prévios, procurou atendimento em UBS, pois, em um exame admissional, fora constatada uma PA de 170 x 100 mmHg. Negou história familiar de hipertensão arterial e doenças prévias. Ao exame físico na UBS, tinha PA de 200 x 100 mmHg e estava assintomático, sem outras alterações. Assinale a alternativa que apresenta a abordagem inicial correta para o paciente.",
  alternativas:[{id:"A",texto:"Nenhum exame deverá ser solicitado por tratar-se de paciente jovem. Somente o controle da PA deverá ser feito."},{id:"B",texto:"Somente exames cardiológicos (ECG, radiografia de tórax e ecocardiograma) deverão ser solicitados."},{id:"C",texto:"Deverão ser solicitados os exames cardiológicos, de glicemia de jejum, de colesterol total e frações e de triglicerídeos."},{id:"D",texto:"Deverão ser solicitados Doppler de artéria renal, atividade de renina e aldosterona."},{id:"E",texto:"Os exames de urina I, ureia, creatinina, potássio, glicemia de jejum, colesterol, HDL, triglicerídeos e ácido deverão ser solicitados."}],
